import {
  createFlowRefResolver,
  resolveAndMigrateWorkflow
} from "./packager-tool-54b4v7wp.js";
import {
  executeWritePlan,
  inMemoryWorkflowToFileFormat,
  planWriteThrough
} from "./packager-tool-e8td7b01.js";
import {
  catchError,
  logger
} from "./packager-tool-79gws1zn.js";
import {
  getFileSystem
} from "./packager-tool-0v3s8r01.js";

// ../flow-tool/src/utils/flow-io.ts
async function readFlowWorkflow(filePath) {
  const fs = getFileSystem();
  const content = await fs.readFile(filePath, "utf-8");
  const parsed = JSON.parse(content);
  return resolveAndMigrateWorkflow(parsed, createFlowRefResolver(fs, logger), filePath, logger);
}
async function writeFlowWorkflow(filePath, workflow, refMap = new Map) {
  const fs = getFileSystem();
  const fileFormat = inMemoryWorkflowToFileFormat(workflow);
  const plan = planWriteThrough(fileFormat, refMap);
  await executeWritePlan(plan, {
    writeMainFile: async (content) => {
      logger.debug(`writeFlowWorkflow: writing main file ${filePath} (${content.length} bytes)`);
      await fs.writeFile(filePath, content);
    },
    writeRefFile: async (refPath, content) => {
      const baseDir = fs.path.dirname(filePath);
      const resolvedPath = fs.path.resolve(baseDir, refPath);
      logger.debug(`writeFlowWorkflow: writing ref chunk ${refPath} → ${resolvedPath} (${content.length} bytes)`);
      await fs.writeFile(resolvedPath, content);
    }
  });
}
async function resolveProjectFlowFile(projectPath) {
  const fs = getFileSystem();
  const [, uiproj] = await catchError((async () => {
    const raw = await fs.readFile(fs.path.join(projectPath, "project.uiproj"), "utf-8");
    return JSON.parse(raw);
  })());
  const safeName = uiproj?.Name?.replace(/[^a-zA-Z0-9_-]/g, "_");
  return findProjectFlowFile(projectPath, uiproj?.MainFile, safeName);
}
async function findProjectFlowFile(projectPath, mainFile, preferredBaseName) {
  const fs = getFileSystem();
  if (mainFile?.endsWith(".flow")) {
    const mainFilePath = fs.path.join(projectPath, mainFile);
    if (await fs.exists(mainFilePath)) {
      return mainFilePath;
    }
  }
  const preferred = preferredBaseName ? `${preferredBaseName}.flow`.toLowerCase() : undefined;
  const candidateDirs = [
    projectPath,
    fs.path.join(projectPath, "content"),
    fs.path.join(projectPath, "flow_files")
  ];
  for (const dir of candidateDirs) {
    if (!await fs.exists(dir)) {
      continue;
    }
    const stat = await fs.stat(dir);
    if (!stat?.isDirectory()) {
      continue;
    }
    const flowFiles = (await fs.readdir(dir)).filter((entry) => entry.endsWith(".flow"));
    if (flowFiles.length === 0) {
      continue;
    }
    const chosen = (preferred && flowFiles.find((f) => f.toLowerCase() === preferred)) ?? flowFiles[0];
    return fs.path.join(dir, chosen);
  }
  throw new Error(`Missing .flow file in ${projectPath}`);
}

export { readFlowWorkflow, writeFlowWorkflow, resolveProjectFlowFile, findProjectFlowFile };

